create table if not exists public.caleris_development_shop_config (
 singleton boolean primary key default true check (singleton), token_price numeric(20,2) not null default 0 check (token_price >= 0), is_active boolean not null default true, updated_by uuid references auth.users(id), updated_at timestamptz not null default now()
);
insert into public.caleris_development_shop_config(singleton,token_price,is_active) values(true,0,true) on conflict(singleton) do nothing;
create table if not exists public.caleris_development_shop_purchases (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), member_id uuid not null references public.members(id), account_id uuid not null references public.caleris_development_accounts(id), token_type text not null check(token_type in ('TDP','DDP')), quantity numeric(20,2) not null check(quantity > 0), unit_price numeric(20,2) not null check(unit_price >= 0), total_price numeric(20,2) not null check(total_price >= 0), bank_account_id uuid not null references public.economy_wallet_accounts(id), created_at timestamptz not null default now()
);
create index if not exists caleris_development_shop_purchases_user_idx on public.caleris_development_shop_purchases(user_id,created_at desc);
create table if not exists public.caleris_development_season_snapshots (
 id uuid primary key default gen_random_uuid(), season_id uuid not null references public.license_seasons(id), member_id uuid references public.members(id), team_id uuid references public.teams(id), asset_type text not null check(asset_type in ('DDP','TDP')), attributes jsonb not null, created_at timestamptz not null default now()
);
create unique index if not exists caleris_dev_snapshot_member_uq on public.caleris_development_season_snapshots(season_id,asset_type,member_id) where member_id is not null;
create unique index if not exists caleris_dev_snapshot_team_uq on public.caleris_development_season_snapshots(season_id,asset_type,team_id) where team_id is not null;
alter table public.caleris_development_shop_config enable row level security; alter table public.caleris_development_shop_purchases enable row level security; alter table public.caleris_development_season_snapshots enable row level security;
drop policy if exists caleris_development_shop_config_read on public.caleris_development_shop_config; create policy caleris_development_shop_config_read on public.caleris_development_shop_config for select to authenticated using(true);
drop policy if exists caleris_development_shop_config_admin on public.caleris_development_shop_config; create policy caleris_development_shop_config_admin on public.caleris_development_shop_config for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=auth.uid())) with check(exists(select 1 from public.site_admins a where a.user_id=auth.uid()));
drop policy if exists caleris_development_shop_purchases_own_read on public.caleris_development_shop_purchases; create policy caleris_development_shop_purchases_own_read on public.caleris_development_shop_purchases for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.site_admins a where a.user_id=auth.uid()));
drop policy if exists caleris_development_season_snapshots_read on public.caleris_development_season_snapshots; create policy caleris_development_season_snapshots_read on public.caleris_development_season_snapshots for select to authenticated using(true);
revoke all on public.caleris_development_shop_config,public.caleris_development_shop_purchases,public.caleris_development_season_snapshots from anon,authenticated; grant select on public.caleris_development_shop_config,public.caleris_development_shop_purchases,public.caleris_development_season_snapshots to authenticated;
create or replace function public.admin_set_development_shop_price(p_token_price numeric,p_is_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'Admin only.'; end if; if p_token_price is null or p_token_price<0 or p_token_price<>round(p_token_price,2) then raise exception 'Harga token tidak valid.'; end if; insert into public.caleris_development_shop_config(singleton,token_price,is_active,updated_by,updated_at) values(true,p_token_price,p_is_active,auth.uid(),now()) on conflict(singleton) do update set token_price=excluded.token_price,is_active=excluded.is_active,updated_by=excluded.updated_by,updated_at=now(); return jsonb_build_object('token_price',p_token_price,'is_active',p_is_active); end; $$;
create or replace function public.member_purchase_development_tokens(p_quantity numeric) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_member public.members%rowtype; v_profile public.profiles%rowtype; v_cfg public.caleris_development_shop_config%rowtype; v_bank public.economy_wallet_accounts%rowtype; v_dev public.caleris_development_accounts%rowtype; v_type text; v_total numeric(20,2); v_purchase uuid; begin if auth.uid() is null then raise exception 'Authentication required.'; end if; if p_quantity is null or p_quantity<=0 or p_quantity<>round(p_quantity,2) or p_quantity>100000000 then raise exception 'Jumlah token tidak valid.'; end if; select * into v_profile from public.profiles where user_id=auth.uid(); if v_profile.member_id is null then raise exception 'Akun belum terhubung ke member.'; end if; select * into v_member from public.members where id=v_profile.member_id for update; if v_member.role not in ('Owner','Principal','Driver') then raise exception 'Shop hanya tersedia untuk Team Owner dan Driver.'; end if; v_type:=case when v_member.role='Driver' then 'DDP' else 'TDP' end; select * into v_cfg from public.caleris_development_shop_config where singleton=true; if not found or not v_cfg.is_active then raise exception 'Development Shop sedang nonaktif.'; end if; v_total:=round(p_quantity*v_cfg.token_price,2); select * into v_bank from public.economy_wallet_accounts where account_kind='vreeo_bank' and is_active=true for update; if not found then raise exception 'VreeoBank belum tersedia.'; end if; if v_total>0 and v_bank.balance<v_total then raise exception 'Saldo VreeoBank tidak mencukupi.'; end if; if v_type='DDP' then select * into v_dev from public.caleris_development_accounts where asset_type='DDP' and member_id=v_member.id for update; else if v_member.team_id is null then raise exception 'Team Owner belum memiliki tim.'; end if; select * into v_dev from public.caleris_development_accounts where asset_type='TDP' and team_id=v_member.team_id for update; end if; if v_dev.id is null then raise exception 'Development wallet belum tersedia.'; end if; if v_total>0 then update public.economy_wallet_accounts set balance=balance-v_total,updated_at=now() where id=v_bank.id; end if; update public.caleris_development_accounts set balance=balance+p_quantity,updated_at=now() where id=v_dev.id; insert into public.caleris_development_ledger(account_id,delta,source_type,description,idempotency_key,created_by,metadata) values(v_dev.id,p_quantity,'shop_purchase','Pembelian token development dari VreeoBank','shop:'||gen_random_uuid()::text,auth.uid(),jsonb_build_object('unit_price',v_cfg.token_price,'total_price',v_total,'token_type',v_type)); insert into public.caleris_development_shop_purchases(user_id,member_id,account_id,token_type,quantity,unit_price,total_price,bank_account_id) values(auth.uid(),v_member.id,v_dev.id,v_type,p_quantity,v_cfg.token_price,v_total,v_bank.id) returning id into v_purchase; return jsonb_build_object('purchase_id',v_purchase,'token_type',v_type,'quantity',p_quantity,'unit_price',v_cfg.token_price,'total_price',v_total,'remaining_bank_balance',v_bank.balance-v_total); end; $$;
create or replace function public.admin_snapshot_development_season(p_season_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_count integer:=0; v_total integer:=0; begin if not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'Admin only.'; end if; if not exists(select 1 from public.license_seasons where id=p_season_id) then raise exception 'Season tidak ditemukan.'; end if; insert into public.caleris_development_season_snapshots(season_id,member_id,asset_type,attributes) select p_season_id,a.member_id,'DDP',coalesce(jsonb_object_agg(d.attribute_key,d.current_value),'{}'::jsonb) from public.caleris_development_accounts a left join public.caleris_driver_development_attributes d on d.member_id=a.member_id where a.asset_type='DDP' and a.member_id is not null group by a.member_id on conflict(season_id,asset_type,member_id) where member_id is not null do update set attributes=excluded.attributes; get diagnostics v_count=row_count; v_total:=v_total+v_count; insert into public.caleris_development_season_snapshots(season_id,team_id,asset_type,attributes) select p_season_id,a.team_id,'TDP',coalesce(jsonb_object_agg(d.part_key,d.current_value),'{}'::jsonb) from public.caleris_development_accounts a left join public.caleris_team_development_parts d on d.team_id=a.team_id where a.asset_type='TDP' and a.team_id is not null group by a.team_id on conflict(season_id,asset_type,team_id) where team_id is not null do update set attributes=excluded.attributes; get diagnostics v_count=row_count; v_total:=v_total+v_count; return jsonb_build_object('season_id',p_season_id,'snapshots_written',v_total); end; $$;
grant execute on function public.admin_set_development_shop_price(numeric,boolean),public.member_purchase_development_tokens(numeric),public.admin_snapshot_development_season(uuid) to authenticated;